// Reuse the archived London graph; do not edit or duplicate its coordinates by hand.
import fs from 'node:fs';
const source=fs.readFileSync('Rolls-Royce Spectre Black Badge simulator.html','utf8');
function declaration(name,end){const start=source.indexOf('const '+name+' ='),stop=source.indexOf(end,start);if(start<0||stop<0)throw Error('Missing archived London declaration: '+name);return source.slice(start,stop+end.length);}
const text=`/* London graph and district profiles from the archived Spectre simulator.\n   Generated by build-london-data.mjs. Coordinates remain unchanged. */\n(function(root){function create(){\n${declaration('n',';')}\n${declaration('LDN_NODES','];')}\n${declaration('r',';')}\n${declaration('LDN_ROADS','];')}\n${declaration('LDN_LOOK','};')}\n${declaration('LDN_OPEN','];')}\n${declaration('LDN_MARKS','};')}\nconst nodes=LDN_NODES,byId=Object.fromEntries(nodes.map(n=>{n.roads=[];return[n.id,n]})),roads=LDN_ROADS.map(r=>{const A=byId[r.a],B=byId[r.b],dx=(B.e-A.e)*1000,dz=(B.n-A.n)*1000,road={...r,A,B,len:Math.hypot(dx,dz),brg:Math.atan2(dx,dz)};A.roads.push({road,out:1});B.roads.push({road,out:-1});return road;});return {LDN:{nodes,byId,roads},londonLook:LDN_LOOK,londonOpen:LDN_OPEN,londonMarks:LDN_MARKS,WIDTH_SCALE:1.55};\n}root.MUCSLondonData={create};})(typeof window==='undefined'?globalThis:window);\n`;
fs.writeFileSync('tools/vehicle-refinements/london-data.js',text);
